WFJ.Data.add("gossip", {
  ["8a03e99b0187af7d"] = { "Ho appena finito di vagare.", "." },
  ["8a0aaf2980ebe804"] = { "Eldrin è l'unico nella ⟦Elwynn Forest=Foresta di Elwynn⟧ che chiamerei sarto. Lo trovi all'Eastvale Lumber Camp, se ti interessa imparare la professione.", "." },
  ["8a0cee5989b1922d"] = { "Aspetta qui, {name}. Spybot farà uscire Lescovar il prima possibile. Stai all'erta! Attacca solo dopo aver sentito la loro conversazione.", "." },
  ["8a1353802eda3ae0"] = { "Un'altra bella giornata davvero.", "." },
  ["8a224db193eda15b"] = { "Uff... questi parassiti non mi danno tregua notte e giorno! Non li hai visti?\n\nVorrei poter saltare giù per un tubo per sfuggirgli...", "." },
  ["8a23a9e73edb25ee"] = { "Sì! Voglio dell'altro favoloso ⟦Noggenfogger Elixir=Elisir di Granstrippo⟧!", "." },
  ["8a253e14ba179fcd"] = { "Un tempo il più grande centro di produzione aurifera delle terre umane, le ⟦Deadmines=Miniere della Morte⟧ sono ora abitate dalla ⟦Defias Brotherhood=Fratellanza dei Defias⟧, che ha trasformato le buie gallerie nel proprio santuario privato. Si dice che i ladri abbiano arruolato gli astuti goblin perché li aiutino a costruire qualcosa di terribile in fondo alle miniere, ma di cosa si tratti resta ancora incerto. Si vocifera che l'accesso alle ⟦Deadmines=Miniere della Morte⟧ passi per il tranquillo e modesto villaggio di ⟦Moonbrook=Rivoluna⟧.", "." },
  ["8a2b0b7579d0de76"] = { "Il ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧ è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo conquisterà!", "." },
  ["8a2c7b4b381a45e5"] = { "Dove posso trovare parti di ragno delle cripte, Leopold?", "." },
  ["8a31fdd93c455294"] = { "Proviamoci...", "." },
  ["8a3471168129dda3"] = { "Fu volontà di Ragnaros che Obsidion venisse costruito. Obsidion distruggerà gli orchi ⟦Blackrock=Roccianera⟧ dei ⟦Blackrock Spire=Bastioni di Roccianera⟧, unendoci ai nostri fratelli nelle profondità infuocate.", "." },
  ["8a3e32f8fb3420ef"] = { "Tutto è compiuto, giovane {class}. Proprio mentre parliamo, sia l'⟦Horde=Orda⟧ sia l'⟦Alliance=Alleanza⟧ stanno trasportando gli ultimi beni per la guerra a ⟦Silithus=Silitus⟧, vicino alla ⟦Cenarion Hold=Fortezza Cenariana⟧, un'operazione che dovrebbe concludersi in meno di un giorno. Dopodiché si potrà suonare il gong presso i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧, e la guerra avrà inizio.", "." },
  ["8a41ae5e26fcf17f"] = { "Stanotte le stelle saranno perfette!", "." },
  ["8a425b00da99a2db"] = { "Gli occhi di %s si illuminano di rosso mentre accende la dinamite e comincia a sghignazzare come un folle!", "." },
  ["8a456242cdfebe94"] = { "Troverai il maestro delle viverne a Orgrimmar. Per arrivarci va' a nord lungo la strada e chiedi altre indicazioni a un ⟦Orgrimmar Grunt=Grunt di Orgrimmar⟧.", "." },
  ["8a5420d5f2846f34"] = { "%s ti indica il Gizmotronic Apparatus.", "." },
  ["8a55c0af0d55c0dd"] = { "Hai fatto di tutto, <straniero/straniera>, e hai la mia gratitudine. Ti ho promesso di proseguire il tuo addestramento, e ora manterrò la promessa.", "." },
  ["8a570f869b5eb860"] = { "Lo farò, Tirion.", "." },
  ["8a5ae9b96e4fbd6b"] = { "Che cosa vuoi?", "." },
  ["8a5b790db44bbb01"] = { "La tua anima è dannata!", "." },
  ["8a5d672d99570cf4"] = { "Abbi cura di te! Io me ne vado da qui.", "." },
  ["8a7679ad00b693cb"] = { "Il rogo dell'Uomo di Paglia comincerà tra trenta minuti! Vieni alla festa, appena a ovest di ⟦Undercity=Sepulcra⟧, e celebra la Veglia delle Ombre e la nostra liberazione dal Flagello!", "." },
  ["8a79bace113b58c9"] = { "Tark, che è successo là dentro? Lo sai che vali più di così! Squadra blu, presto avrete quel che vi meritate!", "." },
  ["8a7aa422a6c34d8a"] = { "Queste terre saranno purificate!", "." },
  ["8a863ede2a29941a"] = { "La casa d'aste si trova sulla guglia centrale di ⟦Thunder Bluff=Picco del Tuono⟧. Cerca vicino alla base della Windrider's Tower. Che i tuoi antenati veglino su di te.", "." },
  ["8a969f479ad07ae4"] = { "Troverai quel goblin e il suo negozio di giocattoli nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["8a971eb7f096b690"] = { "%s comincia a frugare tra gli averi dello speziale.", "." },
  ["8aa6af9f59fc5687"] = { "Là fa freddo! Tu va in Royal Quarter, parla con ⟦Grizzle Halfmane=Grizzle Mezzachioma⟧.", "." },
  ["8aa78629a1741a96"] = { "Mostrami dove posso volare.", "." },
  ["8aab39bedbe406c8"] = { "Distogliete lo sguardo, bambini. La furia del sangue ha preso il sopravvento...", "." },
  ["8ab43c9c9c006459"] = { "Non risveglierai mai il sognatore!", "." },
  ["8ac6a9d3f236ddb9"] = { "Grazie per il tuo impegno, {name}. Ultimamente c'è stata un'ondata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e al resto penseremo noi.\n\nEcco il tuo compenso.", "." },
  ["8ac6ded5b124ceb7"] = { "Mi sembra di vedere qualcosa.", "." },
  ["8acd9973891e3199"] = { "Sento odore di ladro.", "." },
  ["8add11d98b1b84e2"] = { "Il compito delle Staffette è garantire la sicurezza di chi viaggia attraverso le pianure di Mulgore. Chi minaccia la sicurezza della patria dei tauren rischia di subire la nostra punizione.", "." },
  ["8ae2436743eec2c5"] = { "Che bello vedere una faccia amica. Lo speziale Johaan non mi rivolge molte chiacchiere, a meno che non voglia qualcosa. È uscito dalla tomba da troppo tempo. Un giorno diventerò così anch'io, dicono. Inquietante. Magari a quel punto non me ne importerà più.", "." },
  ["8aea483c819fc34c"] = { "In edificio di ⟦War Quarter=Quartiere della Guerra⟧ su anello esterno di città.", "." },
  ["8af53e6d95121543"] = { "Tre urrà per {name}! Questa terra tornerà a essere nostra!", "." },
  ["8af7ab8acbe34e68"] = { "L'anima di mio figlio non troverà conforto in questa vittoria vuota, drago. Lo riavrò. Dovesse volerci un millennio, io RIAVRÒ mio figlio!", "." },
  ["8afa1e23c629861b"] = { "Salve! E <benvenuto/benvenuta>! Temo che il mio stand non sia aperto... servono molte riparazioni...\n\nMa un giuramento di sangue mi obbliga comunque a farti sorridere. Quindi ti prego, sorridi, o dovrò tagliarmi la mano e non mangiare carne viva finché non ricresce...", "." },
})
